<div class="page-head"><div><h1><?= te('Import employee spreadsheets') ?></h1><p class="sub"><?= te('CSV and XLSX · preview and map identity, employee category, payment method, ADP ID, assignment dates, shift and rates. Unknown columns stay encrypted for review. Hotel, vehicle and historical finance records require separate reconciliation.') ?></p></div></div><?php if($error): ?><div class="flash err"><?= e($error) ?></div><?php endif; ?><form class="card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="do" value="preview"><label><?= te('Employee roster file') ?></label><input name="sheet" type="file" accept=".csv,.xlsx" required><button class="btn"><?= te('Preview file') ?></button></form>
<?php if($preview): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="commit"><h2><?= e($preview['filename']) ?> · <?= count($preview['data']) ?> rows</h2><fieldset class="plain-fieldset m0 mb-l" id="import-target"><legend class="semibold"><?= te('What the people in this file become') ?></legend>
<label class="own-room"><input type="radio" name="target" value="roster" checked> <?= te('Employees, offered an assignment on the working project') ?></label>
<label class="own-room"><input type="radio" name="target" value="applicants"> <?= te('Applicants to a requisition (from a job board), to be screened and offered') ?></label>
<select name="vacancy_id" aria-label="<?= te('Requisition') ?>" class="mt-xs"><option value=""><?= te('Choose the requisition…') ?></option><?php foreach ($openVacancies as $ov): ?><option value="<?= (int) $ov['id'] ?>"><?= e($ov['project'] . ' · ' . $ov['title']) ?></option><?php endforeach; ?></select>
<label class="own-room"><input type="radio" name="target" value="pool"> <?= te('The talent pool only, on no project') ?></label>
</fieldset>
<p class="small muted"><?= te('Matching employee IDs/emails go into review without changing existing records.') ?></p><div class="grid g2"><?php foreach($fields as $field): ?><div><label><?= e($field) ?></label><select name="mapping[<?= e($field) ?>]"><?php $g = $guess($field, $preview['headers']); ?><option value=""><?= te('Not mapped') ?></option><?php foreach($preview['headers'] as $i=>$header): ?><option value="<?= $i ?>"<?= $g === (string) $i ? ' selected' : '' ?>><?= e($header) ?></option><?php endforeach; ?></select></div><?php endforeach; ?></div><div class="scroll"><table><tr><?php foreach($preview['headers'] as $h): ?><th><?= e($h) ?></th><?php endforeach; ?></tr><?php foreach(array_slice($preview['data'],0,5) as $line): ?><tr><?php foreach($line as $value): ?><td><?= e($value) ?></td><?php endforeach; ?></tr><?php endforeach; ?></table></div><button class="btn"><?= te('Import mapped records') ?></button></form><?php endif; ?>
<div class="card"><h2><?= te('Import audit') ?></h2><?php foreach($batches as $b): ?><p><?= e($b['filename']) ?> · <?= (int)$b['row_count'] ?> source rows · <?= (int)$b['imported'] ?> imported · <?= (int)$b['duplicates'] ?> duplicate reviews · <?= (int)$b['invalid'] ?> invalid</p><?php endforeach; ?></div><div class="card"><h2><?= te('Rows needing review') ?></h2><?php foreach($reviews as $r): ?><p>Batch <?= (int)$r['batch_id'] ?> · row <?= (int)$r['row_number'] ?> · <?= e($r['status'].' · '.$r['full_name'].' · '.$r['note']) ?></p><?php endforeach; ?></div>